import Vue from 'vue';
import { parseBoolean } from '@gitlab/frontend-utils';
import { initVueApp } from '~/lib/utils/vue3compat/init_vue_app';
import Translate from '~/vue_shared/translate';
import CleanupImageTags from './components/cleanup_image_tags.vue';
import { apolloProvider } from './graphql/index';

Vue.use(Translate);

export default () => {
  const el = document.getElementById('js-registry-settings-cleanup-image-tags');
  if (!el) {
    return null;
  }
  const {
    isAdmin,
    enableHistoricEntries,
    projectPath,
    adminSettingsPath,
    projectSettingsPath,
    tagsRegexHelpPagePath,
    helpPagePath,
  } = el.dataset;
  return initVueApp({
    el,
    name: 'PackagesCleanupImageTagsRoot',
    apolloProvider,
    provide: {
      isAdmin: parseBoolean(isAdmin),
      enableHistoricEntries: parseBoolean(enableHistoricEntries),
      projectPath,
      adminSettingsPath,
      projectSettingsPath,
      tagsRegexHelpPagePath,
      helpPagePath,
    },
    component: CleanupImageTags,
  });
};
